public class AppVersionTest {

    @Test
    public void parseName_InvalidInput_ReturnsNull() {
        assertNull(AppVersion.parseName(null));
        assertNull(AppVersion.parseName("invalid"));
    }

    @Test
    public void parseName_MatchesPattern_ReturnsParsedAppVersion() {
        AppVersion parsed = AppVersion.parseName("subscriberha-1.0.0-586499");
        assertEquals("subscriberha", parsed.packageName);
        assertEquals("1.0.0-586499", parsed.version);
        assertNull(parsed.buildNumber);
        assertNull(parsed.commit);
        assertNull(parsed.buildJobName);
    }

    @Test
    public void parseName_MatchesPattern_BuildFirst_ReturnsParsedAppVersion() {
        AppVersion parsed = AppVersion.parseName("subscriberha-h1.0.0-586499");
        assertEquals("subscriberha", parsed.packageName);
        assertEquals("h1.0.0-586499", parsed.version);
        assertNull(parsed.buildNumber);
        assertNull(parsed.commit);
        assertNull(parsed.buildJobName);
    }

    @Test
    public void parseName_MatchesPattern_BuildSecond_ReturnsParsedAppVersion() {
        AppVersion parsed = AppVersion.parseName("subscriberha/WE-WAPP-subscriberha/1.0.0-586499");
        assertEquals("subscriberha", parsed.packageName);
        assertEquals("1.0.0-586499", parsed.version);
        assertNull(parsed.buildNumber);
        assertNull(parsed.commit);
        assertEquals("WE-WAPP-subscriberha", parsed.buildJobName);
    }

